<?php
namespace App\Models;
use Illuminate\Foundation\Auth\User as Authenticatable; use Illuminate\Notifications\Notifiable; use Illuminate\Database\Eloquent\Factories\HasFactory;
class User extends Authenticatable { use HasFactory,Notifiable; protected $primaryKey='user_id'; public $incrementing=true; protected $fillable=['role_id','name','email','password','phone','status']; protected $hidden=['password','remember_token']; protected function casts():array{return ['password'=>'hashed','created_at'=>'datetime','updated_at'=>'datetime'];} public function role(){return $this->belongsTo(Role::class,'role_id','role_id');} public function addresses(){return $this->hasMany(Address::class,'user_id','user_id');} public function orders(){return $this->hasMany(Order::class,'user_id','user_id');} public function reviews(){return $this->hasMany(Review::class,'user_id','user_id');} public function wishlists(){return $this->hasMany(Wishlist::class,'user_id','user_id');} public function isAdmin(){return (int)$this->role_id===1;}}
